#include <iostream>
#include <algorithm>
#include <map>

int main() {
    int x, y;
    std::cin >> x >> y;
    if (x > y) std::swap(x, y);
    int calc = x * y;
    std::map<int, int> adjustment = {
        {1, std::min(y % 6, 6 - y % 6)},
        {2, 2 * (y == 3 || y == 7) + 4 * (y == 2)}
    };
    int result;
    if (adjustment.count(x)) {
        result = calc - adjustment[x];
    } else {
        result = calc - ((x & 1) * (y & 1));
    }
    std::cout << result << std::endl;
    return 0;
}
